__bsigFill({"waterchurch":function(K){
// 개략(추정): 예배당 15×15 m 높이 6.4(정면 +z 전면 유리 미닫이) · 그 뒤 모서리에 겹친 10×10 유리 상자(높이 5.5, 네 면 안쪽에 콘크리트 십자가) · 정면 연못 45×32 m 3단(각 15 cm 낮아짐), 십자가 5 m · L자 콘크리트 담(높이 3.4) — 동쪽 긴 변 48 m + 뒤 32 m · 진입은 담 바깥을 따라 돌아 상자로 올라간 뒤 계단으로 내려옴
    const C=K.col(0xcfcac0,{roughness:.9}), C2=K.col(0xbdb8ae,{roughness:.9}), GL=K.col(0xbfd6de,{roughness:.05,metalness:.5,transparent:true,opacity:.28,depthWrite:false}), ST=K.col(0x8a9094,{roughness:.4,metalness:.7}), DK=K.col(0x2a2a2a,{roughness:.8});
    const H=6.4, t=.4, CH=5.5;
    K.layer(0);
    K.b(0,-.02,0,70,.04,80,K.M.grass);
    // 연못: 3단 (뒤 → 앞으로 낮아짐)
    K.b(0,0,12,46,.35,9,C2); K.water(0,.37,12,45,8.6); K.b(0,0,21,46,.25,9,C2); K.water(0,.27,21,45,8.6); K.b(0,0,30.5,46,.15,10,C2); K.water(0,.17,30.5,45,9.6);
    K.b(0,.37,16.5,.4,5.6,.4,ST); K.b(0,4.1,16.5,3.4,.4,.4,ST); // 연못 위 강철 십자가
    // 예배당 15×15: 바닥·세 벽(뒤·동·서) + 정면 전면 유리(미닫이 틀)
    K.b(0,0,0,15,.3,15,C); K.b(0,.3,0,14.2,.03,14.2,DK);
    K.b(0,0,-7.5+t/2,15,H,t,C); K.b(7.5-t/2,0,0,t,H,15,C); K.b(-7.5+t/2,0,-1.25,t,H,12.5,C);
    K.b(0,.3,7.4,15,H-.3,.08,GL); for(const x of [-7.3,-3.7,0,3.7,7.3]) K.b(x,.3,7.4,.14,H-.3,.14,ST); K.b(0,H-.25,7.4,15,.25,.2,ST);
    K.b(2.5,0,7.8,.2,.4,15,C2); // 유리문 앞 턱
    // 안: 벤치 6열 + 제단 쪽 바닥
    for(let i=0;i<5;i++) for(const s of [-1,1]) K.b(s*3,.33,-4+i*1.8,4.6,.45,.4,K.M.wood);
    // L자 담: 동쪽(+x) 긴 변 48 m(뒤에서 연못 끝까지) + 뒤(-z) 32 m
    K.b(23.5,0,8,t,3.4,48,C); K.b(7.5,0,-16,32,3.4,t,C); K.b(-12.4,0,-12,t,3.4,8,C);
    K.b(16,0,8,14,.06,48,K.M.pave); // 담 안쪽 통로
    K.layer(1);
    // 위 유리 상자 10×10 (예배당 뒤 서쪽 모서리에 겹침): 바닥판 + 유리 + 네 면 콘크리트 십자가 + 지붕판
    const cx=-7.5, cz=-7.5; K.b(cx,H,cz,10.4,.3,10.4,C); K.b(cx,H+.3,cz,.4,CH,10,C); // 바닥판·예배당과 만나는 구조 벽
    for(const [x,z,w,d] of [[cx,cz+5,10,.06],[cx,cz-5,10,.06],[cx+5,cz,.06,10],[cx-5,cz,.06,10]]) K.b(x,H+.3,z,w,CH,d,GL);
    for(const [x,z,ax] of [[cx,cz+4.3,'z'],[cx,cz-4.3,'z'],[cx+4.3,cz,'x'],[cx-4.3,cz,'x']]){ K.b(x,H+.3,z,.3,CH,.3,C2); if(ax==='z') K.b(x,H+2.7,z,3.2,.3,.3,C2); else K.b(x,H+2.7,z,.3,.3,3.2,C2); }
    for(const [x,z] of [[cx+5,cz+5],[cx-5,cz+5],[cx+5,cz-5],[cx-5,cz-5]]) K.b(x,H+.3,z,.2,CH,.2,ST);
    K.b(cx,H+.3+CH,cz,10.4,.3,10.4,C);
    // 상자에서 예배당으로 내려가는 계단(바깥 서쪽 — 곡면 계단을 직선으로 단순화)
    for(let i=0;i<10;i++) K.b(-13.5,H-.6*(i+1),-2+i*.9,2.6,.15,.9,C2); K.b(-15,0,2,.3,H,10,C);
    // 지붕
    K.layer(2); K.b(0,H,0,15.4,.35,15.4,C);
    for(const [x,z,h] of [[-20,-10,9],[-24,0,8],[28,-12,10],[31,-2,9],[-18,-22,9],[8,-23,8],[-4,-25,10],[-26,36,8],[27,38,9],[0,46,8],[-16,48,9],[16,48,8]]) K.tree(x,z,h);
  }});
